import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Count opponent cooperation/defection tendencies
    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c
    coop_rate = opp_c / n

    # Detect runs of opponent defection
    def_run = 0
    for _, o in reversed(history):
        if o == 'D':
            def_run += 1
        else:
            break

    # Early game: be generous but responsive
    if n < 5:
        if opp_last == 'D':
            # immediate mild retaliation
            return 'D' if rng.random() < 0.6 else 'C'
        return 'C'

    # Endgame: exploit known defectors, avoid being exploited late
    if n >= 95:
        if coop_rate >= 0.85:
            return 'C'
        if coop_rate <= 0.35:
            return 'D'
        # mixed: cooperate if opponent has been nice recently, else defect
        return 'C' if opp_last == 'C' and def_run == 0 else 'D'

    # If opponent is heavily cooperative, cooperate and occasionally test
    if coop_rate >= 0.9 and def_run == 0:
        if n % 17 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # If opponent is heavily defective, defect most of the time, rare forgive
    if coop_rate <= 0.25:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with forgiveness and occasional probing
    if opp_last == 'D':
        if def_run >= 3:
            return 'D'
        # forgive after single defection sometimes
        if rng.random() < 0.35:
            return 'C'
        # retaliate but not permanently
        return 'D' if rng.random() < 0.75 else 'C'

    # opp_last == 'C'
    if n % 23 == 0 and rng.random() < 0.12:
        return 'D'
    # if our own last was D and opponent still cooperated, go back to C
    if my_last == 'D':
        return 'C'
    return 'C'

